{
  "name": "opencode-zellij-indicator",
  "version": "2.2.0",
  "description": "Show the selected OpenCode 2 session's status and title on its Zellij tab",
  "type": "module",
  "exports": {
    "./tui": "./src/index.ts"
  },
  "files": [
    "src",
    "README.md"
  ],
  "scripts": {
    "test": "bun test",
    "e2e": "bun scripts/e2e.ts",
    "typecheck": "tsc --noEmit"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode2",
    "zellij",
    "terminal",
    "tab",
    "status"
  ],
  "author": "Aidan Gallagher",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/aidan-gallagher/opencode-zellij-indicator.git"
  },
  "homepage": "https://github.com/aidan-gallagher/opencode-zellij-indicator#readme",
  "bugs": {
    "url": "https://github.com/aidan-gallagher/opencode-zellij-indicator/issues"
  },
  "dependencies": {
    "@opencode-ai/plugin": "0.0.0-beta-18414",
    "solid-js": "1.9.10"
  },
  "devDependencies": {
    "@types/node": "^22",
    "typescript": "^5"
  }
}
